package com.autocare.platform.order;
import java.time.Instant;
import java.util.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.security.oauth2.jwt.*;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.test.web.servlet.MockMvc;
import static org.mockito.Mockito.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"JWT_SECRET=test-only-secret-with-at-least-32-characters","PAYMENT_LOCAL_TEST_ENABLED=true","PAYMENT_LOCAL_TEST_SECRET="+LocalTestPaymentChannelTest.KEY})
@AutoConfigureMockMvc @ActiveProfiles("local-payment-test")
class RefundHttpTest {
    @Autowired MockMvc mvc;@MockitoBean OrderRefunds refunds;@MockitoBean RefundRecovery recovery;@MockitoBean JwtDecoder decoder;
    @BeforeEach void tokens(){when(decoder.decode(anyString())).thenAnswer(c->{String t=c.getArgument(0);boolean owner=t.equals("owner");String role=owner?"OWNER":t.equals("manager")?"MERCHANT":t.equals("staff")?"STAFF":"TECHNICIAN";return Jwt.withTokenValue(t).header("alg","HS256").subject("1").claim("subject_type",owner?"user":"staff_account").claim("role",role).claim("app_id","merchant-account").claim("merchant_id",1).claim("jti","test").issuedAt(Instant.now()).expiresAt(Instant.now().plusSeconds(600)).build();});}
    @Test void ownerAndManagerBoundariesProtectReadsAndWrites()throws Exception{mvc.perform(get("/api/order/1/refund")).andExpect(status().isUnauthorized());for(String token:List.of("manager","staff","tech"))mvc.perform(get("/api/order/1/refund").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());for(String token:List.of("owner","staff","tech"))mvc.perform(get("/api/merchant/orders/1/refund").header("Authorization","Bearer "+token)).andExpect(status().isForbidden());verifyNoInteractions(refunds,recovery);}
    @Test void clientAmountsStatesAndMissingKeysAreRejected()throws Exception{for(String body:List.of("{\"reason\":\"退\",\"amount\":\"0.01\"}","{\"status\":\"SUCCEEDED\"}","[]","null"))mvc.perform(post("/api/order/1/refund").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content(body)).andExpect(status().isBadRequest());mvc.perform(post("/api/order/1/refund").header("Authorization","Bearer owner").contentType("application/json").content("{\"reason\":\"退款\"}")).andExpect(status().isBadRequest());verifyNoInteractions(refunds);}
    @Test void strictRevisionAndEmptyReconcileBodies()throws Exception{mvc.perform(post("/api/merchant/orders/1/refund/decision").header("Authorization","Bearer manager").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content("{\"revision\":1,\"decision\":\"ACCEPT\",\"amount\":\"0.01\"}")).andExpect(status().isBadRequest());mvc.perform(post("/api/order/1/refund/withdraw").header("Authorization","Bearer owner").header("Idempotency-Key",UUID.randomUUID().toString()).contentType("application/json").content("{\"revision\":0}")).andExpect(status().isBadRequest());mvc.perform(post("/api/merchant/orders/1/refund/reconcile").header("Authorization","Bearer manager").contentType("application/json").content("{\"success\":true}")).andExpect(status().isBadRequest());verifyNoInteractions(refunds,recovery);}
    @Test void roleReadHasNoStore()throws Exception{when(refunds.detail(any(),isNull(),eq(1L))).thenReturn(Map.of("order_id",1));when(refunds.detail(isNull(),any(),eq(1L))).thenReturn(Map.of("order_id",1));mvc.perform(get("/api/order/1/refund").header("Authorization","Bearer owner")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));mvc.perform(get("/api/merchant/orders/1/refund").header("Authorization","Bearer manager")).andExpect(status().isOk()).andExpect(header().string("Cache-Control","no-store"));}
    @Test void signedCallbackAckAndRetryFailure()throws Exception{byte[] raw=LocalRefundChannelTest.body("SUCCEEDED").getBytes(java.nio.charset.StandardCharsets.UTF_8);String time=""+Instant.now().getEpochSecond(),nonce=UUID.randomUUID().toString(),signature=LocalTestPaymentChannelTest.sign(raw,time,nonce);mvc.perform(post("/api/refunds/callback/LOCAL_TEST").contentType("application/json").header("X-Test-Timestamp",time).header("X-Test-Nonce",nonce).header("X-Test-Signature",signature).content(raw)).andExpect(status().isOk()).andExpect(jsonPath("$.code").value("SUCCESS"));verify(recovery).notify(any());doThrow(new org.springframework.dao.DataAccessResourceFailureException("private SQL")).when(recovery).notify(any());mvc.perform(post("/api/refunds/callback/LOCAL_TEST").contentType("application/json").header("X-Test-Timestamp",time).header("X-Test-Nonce",nonce).header("X-Test-Signature",signature).content(raw)).andExpect(status().isServiceUnavailable());}
    @Test void forgedAndOtherChannelsAreRejected()throws Exception{mvc.perform(post("/api/refunds/callback/LOCAL_TEST").contentType("application/json").content("{}")).andExpect(status().isBadRequest());mvc.perform(post("/api/refunds/callback/WECHAT").contentType("application/json").content("{}")).andExpect(status().isUnauthorized());verifyNoInteractions(recovery);}
}
